import {createScene} from './scene.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const names=['小禾','阿远'],planets=['慢慢星','晚风星'],cities=['上海','杭州'];
const foods={milk:['草莓牛奶','🥛'],pudding:['焦糖布丁','🍮'],cookie:['黄油曲奇','🍪'],rice:['米饭','🍚'],egg:['鸡蛋','🥚'],tomato:['番茄','🍅']};
const recipes={omelet:{name:'番茄蛋包饭',icon:'🍛',needs:{rice:1,egg:1,tomato:1}},toast:{name:'暖心蒸蛋',icon:'🍲',needs:{egg:1}},milk:{name:'热草莓牛奶',icon:'🥛',needs:{milk:1}}};
const weatherData={sun:['☀','24°','晴朗，有一点微风','晴'],rain:['☂','21°','小雨，适合窝在家里','雨'],snow:['❄','−1°','雪花轻轻落下','雪'],night:['☾','18°','夜色温柔，灯为你留着','夜']};
const uid=()=>crypto.randomUUID(),key='our-little-skies-v1';
function today(){let d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function initial(){return {version:1,actor:0,worlds:[0,1].map(i=>({weather:i?'rain':'sun',deco:false,fridge:['milk','pudding','rice','egg','tomato'].map(food=>({id:uid(),food,qty:3})),meals:[]})),bags:[{cookie:3,pudding:2,milk:2},{cookie:3,pudding:2,milk:2}],events:[],notes:[],favorites:[[],[]]}}
let state;try{let raw=JSON.parse(localStorage.getItem(key));state=raw?.version===1&&raw.worlds?.length===2&&Array.isArray(raw.events)&&Array.isArray(raw.notes)&&raw.bags&&raw.favorites?raw:initial()}catch{state=initial()}
let actor=state.actor===1?1:0,world=actor,inside=false,visual=null,currentPanel='',journalTab='personal',recipe='omelet',recipient='self',toastTimer,game=null;
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const time=s=>new Date(s).toLocaleString('zh-CN',{month:'short',day:'numeric',hour:'2-digit',minute:'2-digit'});
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3300)}
function save(){state.actor=actor;try{localStorage.setItem(key,JSON.stringify(state))}catch{toast('浏览器无法保存，本次记录暂时保留在页面中。')}recent()}
function weatherStamp(){return state.worlds.map((w,i)=>cities[i]+' · '+weatherData[w.weather][3]).join(' / ')}
function record(title,body,opts={}){const e={id:uid(),title,body,actor,world,target:null,shared:false,pending:false,kind:'life',created:Date.now(),weather:weatherStamp(),steps:[],comments:[],...opts};state.events.unshift(e);save();return e}
function visible(e,shared=false){return shared?e.shared&&!e.pending:e.actor===actor||(!e.pending&&(e.target===actor||e.shared))}
function discover(items){let n=0;for(const item of items){const e=state.events.find(e=>e.id===item.event);if(e?.pending&&e.target===actor){e.pending=false;e.steps.push({text:names[actor]+'发现了这份心意。',at:Date.now()});n++}}if(n){save();toast('发现了 '+n+' 份心意，已经写进手账。')}}
function recent(){if(!$('#recent-events'))return;const list=state.events.filter(e=>visible(e)).slice(0,2);$('#recent-events').innerHTML=list.length?list.map(e=>'<div class="recent-item"><span class="recent-dot"></span><span>'+esc(e.title)+'<small>'+time(e.created)+' · '+planets[e.world]+'</small></span></div>').join(''):'<div class="recent-item"><span class="recent-dot"></span><span>今天的故事，等你写下第一笔。<small>做顿饭，或去对方家里坐坐</small></span></div>'}
function refresh(){const w=state.worlds[world],v=weatherData[w.weather];$('#place').textContent=planets[world]+' · '+cities[world];$('#weather-icon').textContent=v[0];$('#temperature').textContent=v[1];$('#weather-description').textContent=v[2];$('#owner-label').textContent=inside?names[world]+'的小屋 · 欢迎来坐坐':'林间的小小日常';$('#scene-heading').textContent=inside?(world===actor?'回家，把日子过暖。':'来你家，待一会儿。'):(world===actor?'今天，也好好生活。':'看看你那边的天空。');$('#scene-subtitle').textContent=inside?'点一点家具，发现生活里的小事。':world===actor?'风经过树梢。家里还有一点小惊喜。':'带来的心意，可以放进冰箱或留在餐桌上。';$('#enter-home').textContent=inside?'回到院子 ↗':'走进小屋 ↗';$('#scene-hint').textContent=inside?'拖动查看 · 点击家具互动':'拖动旋转 · 点击小屋进入';$('#identity-text').textContent=names[actor]+'的视角';$('.avatar').textContent=names[actor][0];$('#partner-peek').innerHTML='<span class="tiny-orbit">◒</span><span><small>'+planets[1-world]+' · '+cities[1-world]+'</small><b>去'+(world===actor?'对方':'自己')+'的星球坐坐</b></span><span>↗</span>';$$('[data-world]').forEach(b=>b.classList.toggle('active',world===(b.dataset.world==='0'?actor:1-actor)));$$('[data-weather]').forEach(b=>b.classList.toggle('active',b.dataset.weather===w.weather));$$('[data-nav]').forEach(b=>b.classList.toggle('selected',b.dataset.nav===(inside?'home':'planet')));visual?.world(world,w.deco);visual?.weather(w.weather);visual?.food(w.meals.length>0);$('#date-stamp').textContent=new Date().toLocaleDateString('zh-CN',{month:'2-digit',day:'2-digit'});recent()}
function close(){$('#panel').close();currentPanel=''}
function enter(){inside=true;visual?.enter(true);refresh()}
function go(i){world=i;inside=false;visual?.enter(false);close();refresh();toast(world===actor?'回到自己的小星球。':'抵达'+planets[world]+'，这里是'+weatherData[state.worlds[world].weather][3]+'天。')}
function modal(id,kicker,title,html){currentPanel=id;$('#panel-kicker').textContent=kicker;$('#panel-title').textContent=title;$('#panel-body').innerHTML=html;if(!$('#panel').open)$('#panel').showModal()}
const btn=(action,text,primary=false,extra='')=>'<button class="pill '+(primary?'primary':'')+'" data-do="'+action+'" '+extra+'>'+text+'</button>';
function fridge(){enter();discover(state.worlds[world].fridge);modal('fridge','SOMETHING SWEET',names[world]+'的冰箱','<p class="subtle">留一点喜欢的味道。送给对方的食物，会在对方打开冰箱时被发现。</p><div class="chips"><button class="active">冰箱里</button><button data-do="bag">从随身包放入</button></div><div class="grid">'+state.worlds[world].fridge.map(i=>{const f=foods[i.food],e=state.events.find(e=>e.id===i.event);const reserved=e?.pending&&e.target!==actor;return '<div class="item"><span class="count">× '+i.qty+'</span><span class="emoji">'+f[1]+'</span><b>'+f[0]+'</b><small>'+(i.event?'来自'+names[e?.actor??world]+'的心意':'家里的日常储备')+'</small>'+(reserved?'<span class="tag">留给对方 · 等待发现</span>':btn('eat-fridge','吃一份',false,'data-id="'+i.id+'"'))+(!i.event&&world===actor?' '+btn('pack','装进包',false,'data-id="'+i.id+'"'):'')+'</div>'}).join('')+'</div>'+(world===actor?'<div class="form-actions">'+btn('restock','补充基础食材')+'</div>':''))}
function bag(){modal('bag','A LITTLE SOMETHING','随身带着的心意','<p class="subtle">现在位于'+names[world]+'的'+planets[world]+'。放入对方冰箱，就为对方留下一份零食。</p><div class="grid" style="margin-top:18px">'+(Object.entries(state.bags[actor]).filter(([f,q])=>q>0&&foods[f]).map(([f,q])=>'<div class="item"><span class="count">× '+q+'</span><span class="emoji">'+foods[f][1]+'</span><b>'+foods[f][0]+'</b><small>'+(world===actor?'放回自己的冰箱':'给'+names[world]+'留一份')+'</small>'+btn('deposit','放进冰箱',true,'data-food="'+f+'"')+'</div>').join('')||'<div class="empty">包里暂时空了。</div>')+'</div><div class="form-actions">'+btn('snacks','补充三种零食')+'</div><p class="subtle" style="margin-top:12px">原型里的基础食材和零食可免费补充。</p>')}
function amount(f){return state.worlds[world].fridge.filter(i=>i.food===f&&!i.event).reduce((n,i)=>n+i.qty,0)}
function enough(){return Object.entries(recipes[recipe].needs).every(([f,q])=>amount(f)>=q)}
function kitchen(){enter();const r=recipes[recipe];modal('cook','MADE WITH CARE','认真做一顿饭','<p class="subtle">在'+names[world]+'的小屋做饭，使用这里的基础食材。做好后会留在这里的餐桌上。</p><div class="chips">'+Object.entries(recipes).map(([id,r])=>'<button data-do="recipe" data-id="'+id+'" class="'+(id===recipe?'active':'')+'">'+r.icon+' '+r.name+'</button>').join('')+'</div><div class="item"><span class="emoji">'+r.icon+'</span><b>'+r.name+'</b><small>'+Object.entries(r.needs).map(([f,q])=>foods[f][0]+' '+amount(f)+'/'+q).join(' · ')+'</small></div><div class="form-row"><label>这顿饭，想为谁准备？</label><div class="chips">'+[['self','给自己'],['partner','留给'+names[1-actor]],['together','一起做 · 演示']].map(([id,n])=>'<button data-do="recipient" data-id="'+id+'" class="'+(recipient===id?'active':'')+'">'+n+'</button>').join('')+'</div></div><div class="form-row"><label for="meal-message">在饭盒旁留一句话</label><input id="meal-message" maxlength="120" placeholder="回来记得吃，今天也辛苦了。"></div>'+(recipient==='together'?'<p class="subtle">此选项模拟两人共同完成，用来体验双方手账；尚未连接第二位在线玩家。</p>':'')+'<div class="form-actions">'+(!enough()?btn('restock','补充基础食材'):'')+btn('cook-done',enough()?'做好，摆上餐桌':'食材还不够',true,enough()?'':'disabled')+'</div>')}
function cook(){if(!enough())return;const r=recipes[recipe],target=recipient==='self'?actor:1-actor,together=recipient==='together',message=$('#meal-message')?.value.trim()||'';for(const [f,q]of Object.entries(r.needs)){let n=q;for(const i of state.worlds[world].fridge){if(i.food===f&&!i.event){const take=Math.min(i.qty,n);i.qty-=take;n-=take}}}state.worlds[world].fridge=state.worlds[world].fridge.filter(i=>i.qty>0);const e=record(together?'我们一起做了'+r.name:names[actor]+'为'+(target===actor?'自己':names[target])+'做了'+r.name,message||'一顿热乎乎的饭，慢慢吃。',{target,shared:target!==actor,pending:target!==actor&&!together});state.worlds[world].meals.push({id:uid(),recipe,owner:target,event:e.id,together});save();refresh();table();toast('饭做好了，已经摆上餐桌，也记进了手账。')}
function table(){enter();discover(state.worlds[world].meals);modal('table','AT THE TABLE','留在桌上的温暖','<p class="subtle">在'+names[world]+'的小屋，坐下来慢慢吃。留给某人的饭，只有那个人能打开。</p><div class="grid" style="margin-top:18px">'+(state.worlds[world].meals.map(m=>{const r=recipes[m.recipe],e=state.events.find(e=>e.id===m.event);return '<div class="item"><span class="emoji">'+r.icon+'</span><b>'+r.name+'</b><small>'+(m.together?'一起做好的':'留给'+names[m.owner])+'</small><p class="subtle">'+esc(e?.body||'给你留的一顿饭。')+'</p><div style="margin-top:13px">'+(m.owner===actor||m.together?btn('eat-meal','打开饭盒，吃饭',true,'data-id="'+m.id+'"'):'<span class="tag">保温中 · 等对方发现</span>')+'</div></div>'}).join('')||'<div class="empty" style="grid-column:1/-1">餐桌还空着。去厨房，做一顿喜欢的饭。</div>')+'</div><div class="form-actions">'+btn('cook','去厨房',true)+'</div>')}
function listRecords(){if(journalTab==='dates')return state.notes.filter(n=>n.kind==='anniversary'&&(n.actor===actor||n.shared)).sort((a,b)=>a.date.localeCompare(b.date));return [...state.events.filter(e=>visible(e,journalTab==='shared')),...state.notes.filter(n=>journalTab==='shared'?n.shared:n.actor===actor||n.shared)].filter(e=>journalTab!=='favorites'||state.favorites[actor].includes(e.id)).sort((a,b)=>b.created-a.created)}
function card(e){return '<article class="memory"><div class="meta"><span>'+(e.kind==='anniversary'?'◷ 纪念日':e.shared?'♡ 共同记忆':'✎ 个人生活')+(e.pending?' · 等对方发现':'')+'</span><span>'+(e.date||time(e.created))+'</span></div><h3>'+esc(e.title)+'</h3><p>'+esc(e.body)+'</p>'+(e.steps||[]).map(s=>'<div class="reply">'+esc(s.text)+' <span class="subtle">'+time(s.at)+'</span></div>').join('')+(e.comments||[]).map(c=>'<div class="reply"><b>'+names[c.actor]+'</b>：'+esc(c.text)+'</div>').join('')+'<div class="foot">'+planets[e.world]+' · '+(e.weather||'手动记录')+(e.repeat?' · 每年纪念':'')+'</div><div class="inline-actions"><button data-do="favorite" data-id="'+e.id+'">'+(state.favorites[actor].includes(e.id)?'★ 已珍藏':'☆ 珍藏')+'</button><button data-do="reply" data-id="'+e.id+'">添一句话</button>'+(e.actor===actor&&!e.shared?'<button data-do="share" data-id="'+e.id+'">放入共同回忆册</button>':'')+(e.actor===actor?'<button data-do="delete" data-id="'+e.id+'">删除</button>':'')+'</div></article>'}
function journal(tab=journalTab){journalTab=tab;const list=listRecords();modal('journal','OUR LITTLE MEMORIES',tab==='shared'?'我们的共同回忆册':names[actor]+'的生活手账','<div class="cover-mini"><img src="journal-cover.png" alt="两间小屋与一颗小星球的手账封面"><p>为自己、为你、和你一起。<br><span class="subtle">生活足迹自动收好，心情由你亲手写。</span></p></div><div class="chips">'+[['personal','我的足迹'],['shared','共同回忆'],['dates','纪念日'],['favorites','珍藏']].map(([id,n])=>'<button data-do="journal-tab" data-id="'+id+'" class="'+(id===tab?'active':'')+'">'+n+'</button>').join('')+'</div><div class="inline-actions">'+btn('write','＋ 写一页',true)+btn('anniversary','＋ 纪念日')+btn('export','导出本页记录')+'</div><div id="memories">'+(list.map(card).join('')||'<div class="empty" style="margin-top:18px"><img src="journal-cover.png" alt="星球回忆插画">这里还没有记录。去做一件小事，或亲手写一页吧。</div>')+'</div>')}
function write(kind='memory'){modal('write','A PAGE FOR TODAY',kind==='anniversary'?'把重要的日子记下来':'写下此刻的心情','<form id="note-form"><input type="hidden" name="kind" value="'+kind+'"><div class="form-row"><label for="note-title">'+(kind==='anniversary'?'纪念日名称':'这一页的名字')+'</label><input id="note-title" name="title" required maxlength="80" placeholder="'+(kind==='anniversary'?'第一次见面的日子':'今天的一点小幸福')+'"></div><div class="form-row"><label for="note-body">想留下的话</label><textarea id="note-body" name="body" maxlength="2000" placeholder="为自己做了什么？为对方准备了什么？一起经历了什么？"></textarea></div><div class="grid"><div class="form-row"><label for="note-date">日期</label><input type="date" id="note-date" name="date" value="'+today()+'" required></div><div class="form-row"><label for="note-visibility">收在哪里</label><select id="note-visibility" name="visibility"><option value="private">自己的私人手账</option><option value="shared" '+(journalTab==='shared'?'selected':'')+'>两个人的共同回忆册</option></select></div></div>'+(kind==='anniversary'?'<label class="subtle"><input name="repeat" type="checkbox" checked style="width:auto"> 每年纪念这一天（本版仅标记，不发送通知）</label>':'')+'<div class="form-actions"><button type="submit" class="pill primary">收进手账</button></div></form>')}
function decorate(){modal('decorate','MAKE IT YOURS','让家，多一点你的样子','<p class="subtle">'+(world===actor?'给院子放一盆小花，装扮会留在自己的星球上。':'正在对方家做客，装扮需要回到自己的星球。')+'</p><div class="item" style="margin-top:18px"><span class="emoji">🌼</span><b>窗前的金色小花</b><small>一小盆，也能让家变温暖。</small>'+(world===actor?btn('flower',state.worlds[world].deco?'收起花盆':'摆进院子',true):btn('go-own','回自己的星球',true))+'</div>')}
let audio=null,timer=null,musicOn=false;
function stopMusic(){clearInterval(timer);audio?.close();audio=null;musicOn=false}
function playMusic(){if(musicOn){stopMusic();music();return}try{audio=new(window.AudioContext||window.webkitAudioContext)();audio.resume();musicOn=true;const tones=[261.63,329.63,392,523.25,440,392,329.63,293.66];let n=0;const tick=()=>{if(!audio)return;let o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=tones[n++%tones.length];g.gain.setValueAtTime(0,audio.currentTime);g.gain.linearRampToValueAtTime(.05,audio.currentTime+.03);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+1.8);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+2)};tick();timer=setInterval(tick,700);music()}catch{toast('当前浏览器暂时不能播放声音。')}}
function music(){enter();modal('music','A QUIET AFTERNOON','给房间放一点音乐','<div class="item" style="text-align:center"><span class="emoji">♫</span><b>窗边的小小旋律</b><small>一段轻轻循环的合成音符</small>'+(musicOn?'<div class="music-bars"><i></i><i></i><i></i><i></i><i></i></div>':'')+btn('play-music',musicOn?'暂停音乐':'播放音乐',true)+'</div><p class="subtle" style="margin-top:15px">音乐只在当前设备播放，可以随时暂停。</p>')}
function newGame(){let cards=['🍓','🌼','🍮','🌙','🍓','🌼','🍮','🌙'];for(let i=cards.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[cards[i],cards[j]]=[cards[j],cards[i]]}game={cards,open:[],matched:[],moves:0,locked:false,done:false}}
function games(){enter();if(!game)newGame();modal('games','PLAY A LITTLE','茶几上的翻牌游戏','<p class="subtle">找出四组相同的小物件。</p><p class="subtle" style="margin:12px 0">已尝试 '+game.moves+' 次 · 找到 '+game.matched.length/2+'/4 组</p><div class="match-grid">'+game.cards.map((c,i)=>'<button data-do="flip" data-id="'+i+'" aria-label="第 '+(i+1)+' 张牌" class="'+(game.matched.includes(i)?'matched':'')+'" '+(game.locked||game.matched.includes(i)?'disabled':'')+'>'+(game.open.includes(i)||game.matched.includes(i)?c:'✳')+'</button>').join('')+'</div><div class="form-actions">'+btn('new-game','重新洗牌')+'</div>')}
function settings(){modal('settings','PLAYABLE PROTOTYPE','在两个人的生活间切换','<p class="subtle">当前是'+names[actor]+'的视角。切换角色后，可以发现另一位留下的饭和零食，查看各自的手账。</p><div class="chips">'+names.map((n,i)=>'<button data-do="switch-actor" data-id="'+i+'" class="'+(i===actor?'active':'')+'">'+n+' · '+planets[i]+'</button>').join('')+'</div><div class="preview-info">这是单设备交互原型：两位角色、城市与天气为演示，尚未接入真实定位、天气接口、账号或跨设备联机。记录保存在当前浏览器；私人手账的分隔用于演示，不构成真实账号权限。音乐是本地生成的简短旋律。</div><div class="form-actions">'+btn('export-all','导出当前角色全部手账')+'</div>')}
function findRecord(id){return state.events.find(e=>e.id===id)||state.notes.find(e=>e.id===id)}
function reply(id){const e=findRecord(id);if(!e)return;modal('reply','ADD YOUR WORDS','在回忆旁，添一句话','<p class="subtle">'+esc(e.title)+'</p><form id="reply-form" data-id="'+id+'"><div class="form-row"><label for="reply-text">'+names[actor]+'想说</label><textarea id="reply-text" name="text" required maxlength="500"></textarea></div><div class="form-actions"><button type="submit" class="pill primary">留下这句话</button></div></form>')}
function exportRecords(all=false){const list=all?[...state.events.filter(e=>visible(e)),...state.notes.filter(e=>e.actor===actor||e.shared)]:listRecords();const text='# '+names[actor]+'的生活手账\n\n'+list.map(e=>'## '+e.title+'\n'+(e.date||time(e.created))+' · '+planets[e.world]+'\n\n'+e.body+'\n'+(e.steps||[]).map(s=>s.text).join('\n')+'\n'+(e.comments||[]).map(c=>names[c.actor]+'：'+c.text).join('\n')+'\n').join('\n---\n\n');const u=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'})),a=document.createElement('a');a.href=u;a.download=names[actor]+'的生活手账-'+today()+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(u),2000);toast('手账已导出为文字文件。')}
function roomMenu(){enter();modal('room','MAKE YOURSELF AT HOME',names[world]+'的小屋','<p class="subtle">点一件家具，开始一件小事。也可以关掉面板，直接点击立体小屋里的物件。</p><div class="room-list" style="margin-top:20px">'+[['fridge','♧','冰箱'],['cook','♨','厨房'],['table','◯','餐桌'],['journal','▤','书桌手账'],['music','♫','音乐'],['games','✳','小游戏']].map(([a,i,t])=>'<button data-do="'+a+'"><span>'+i+'</span><small>'+t+'</small></button>').join('')+'</div>')}
function act(a){if(a==='home'){enter();return}({fridge,cook:kitchen,table,journal,bag,decorate,music,games,settings,room:roomMenu})[a]?.();if(a==='sit'){modal('sit','TAKE YOUR TIME','坐一会儿，也很好','<p class="subtle">这里是'+weatherData[state.worlds[world].weather][2]+'。想做什么，就慢慢来。</p><div class="room-list" style="margin-top:20px"><button data-do="music"><span>♫</span><small>听段音乐</small></button><button data-do="games"><span>✳</span><small>玩个小游戏</small></button><button data-do="write"><span>▤</span><small>写一页手账</small></button></div>')}if(a==='garden'){record(names[actor]+'给'+(world===actor?'自己的':names[world]+'的')+'花坛浇了水','叶子上留下了亮晶晶的小水珠。',{target:world,shared:world!==actor});toast('花坛喝到水了，这一刻已经记进手账。')}if(a==='pet')toast('小兔子抬起头，轻轻蹭了蹭你的手。')}
const handlers={fridge,bag,cook:kitchen,table,music,games,write:()=>write(),anniversary:()=>write('anniversary'),'go-own':()=>go(actor),'play-music':playMusic,'cook-done':cook,export:()=>exportRecords(),'export-all':()=>exportRecords(true),snacks(){for(let f of ['milk','cookie','pudding'])state.bags[actor][f]=(state.bags[actor][f]||0)+2;save();bag();toast('已补充三种喜欢的零食。')},deposit(b){let f=b.dataset.food;if(!foods[f]||!(state.bags[actor][f]>0))return;state.bags[actor][f]--;const e=record(names[actor]+'给'+(world===actor?'自己':names[world])+'留了一份'+foods[f][0],'放进冰箱的小心意。',{target:world,shared:world!==actor,pending:world!==actor});state.worlds[world].fridge.push({id:uid(),food:f,qty:1,event:world!==actor?e.id:null});save();bag();toast('已经放进冰箱。')},'eat-fridge'(b){let i=state.worlds[world].fridge.find(i=>i.id===b.dataset.id);if(!i||i.qty<=0)return;let e=state.events.find(e=>e.id===i.event);if(e?.pending&&e.target!==actor)return;i.qty--;if(e)e.steps.push({text:names[actor]+'吃了'+foods[i.food][0]+'。',at:Date.now()});else record(names[actor]+'吃了一份'+foods[i.food][0],'照顾好自己，也是一件值得记下的小事。');state.worlds[world].fridge=state.worlds[world].fridge.filter(i=>i.qty>0);save();fridge();toast('慢慢吃，好好享受这一口。')},pack(b){let i=state.worlds[world].fridge.find(i=>i.id===b.dataset.id);if(!i||world!==actor||i.qty<=0)return;i.qty--;state.bags[actor][i.food]=(state.bags[actor][i.food]||0)+1;state.worlds[world].fridge=state.worlds[world].fridge.filter(i=>i.qty>0);save();fridge();toast('已经装进随身包。')},restock(){for(let f of ['rice','egg','tomato','milk']){let i=state.worlds[world].fridge.find(i=>i.food===f&&!i.event);if(i)i.qty+=3;else state.worlds[world].fridge.push({id:uid(),food:f,qty:3})}save();currentPanel==='cook'?kitchen():fridge();toast('基础食材已经补充好。')},recipe(b){if(recipes[b.dataset.id])recipe=b.dataset.id;kitchen()},recipient(b){recipient=b.dataset.id;kitchen()},'eat-meal'(b){let m=state.worlds[world].meals.find(m=>m.id===b.dataset.id);if(!m||(m.owner!==actor&&!m.together))return;let e=findRecord(m.event);if(e)e.steps.push({text:names[actor]+'吃掉了'+recipes[m.recipe].name+'，饭盒空了。',at:Date.now()});state.worlds[world].meals=state.worlds[world].meals.filter(i=>i.id!==m.id);save();refresh();table();toast('吃完了，心里也暖了一点。')},'journal-tab'(b){journal(b.dataset.id)},favorite(b){let a=state.favorites[actor];state.favorites[actor]=a.includes(b.dataset.id)?a.filter(i=>i!==b.dataset.id):[...a,b.dataset.id];save();journal()},reply(b){reply(b.dataset.id)},share(b){let e=findRecord(b.dataset.id);if(e?.actor===actor){e.shared=true;save();journal();toast('已经放入共同回忆册。')}},delete(b){let e=findRecord(b.dataset.id);if(e?.actor!==actor)return;modal('delete','KEEP OR LET GO','删除这条记录？','<p class="subtle">'+esc(e.title)+'<br>删除后将从相关手账中移除，已经送出的食物仍会保留。</p><div class="form-actions">'+btn('cancel-delete','保留')+btn('confirm-delete','删除记录',false,'data-id="'+e.id+'"')+'</div>')},'cancel-delete':()=>journal(),'confirm-delete'(b){const id=b.dataset.id;state.events=state.events.filter(e=>e.id!==id||e.actor!==actor);state.notes=state.notes.filter(e=>e.id!==id||e.actor!==actor);save();journal()},flower(){if(world!==actor)return;let w=state.worlds[world];w.deco=!w.deco;visual?.decorate(w.deco);if(w.deco)record(names[actor]+'在院子里摆了一盆小花','给自己的家，添一点暖黄色。');save();decorate()},'switch-actor'(b){let n=Number(b.dataset.id);if(n!==0&&n!==1)return;actor=n;save();go(actor);toast('现在是'+names[actor]+'的视角。')},'new-game'(){newGame();games()},flip(b){if(!game||game.locked)return;let i=Number(b.dataset.id);if(game.open.includes(i)||game.matched.includes(i))return;game.open.push(i);if(game.open.length===2){game.moves++;if(game.cards[game.open[0]]===game.cards[game.open[1]]){game.matched.push(...game.open);game.open=[];if(game.matched.length===8&&!game.done){game.done=true;record(names[actor]+'完成了茶几上的翻牌游戏','用了'+game.moves+'次尝试，找到了四组小物件。');toast('都找到了！这个小成就已经记进手账。')}}else{game.locked=true;let g=game;setTimeout(()=>{if(g!==game)return;game.open=[];game.locked=false;if(currentPanel==='games')games()},850)}}games()}};
$('#panel-body').addEventListener('click',e=>{const b=e.target.closest('[data-do]');if(b&&!b.disabled)handlers[b.dataset.do]?.(b)});
$('#panel-body').addEventListener('submit',e=>{e.preventDefault();let d=new FormData(e.target);if(e.target.id==='note-form'){let title=String(d.get('title')||'').trim();if(!title)return;let date=String(d.get('date'));state.notes.unshift({id:uid(),actor,world,title,body:String(d.get('body')||'').trim(),date,kind:d.get('kind'),shared:d.get('visibility')==='shared',repeat:d.has('repeat'),created:Date.now(),weather:date===today()?weatherStamp():'',comments:[]});save();journal(d.get('kind')==='anniversary'?'dates':d.get('visibility')==='shared'?'shared':'personal');toast('这一页，已经好好收起来了。')}else if(e.target.id==='reply-form'){let r=findRecord(e.target.dataset.id),text=String(d.get('text')||'').trim();if(r&&text){r.comments??=[];r.comments.push({actor,text,at:Date.now()});save();journal();toast('回忆里，多了你的一句话。')}}});
$('#close-panel').onclick=close;$('#panel').addEventListener('close',()=>{if(!$('#panel').open)currentPanel=''});$('#panel').addEventListener('click',e=>{if(e.target===$('#panel')){let r=$('#panel').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)close()}});
$('#enter-home').onclick=()=>{if(inside){inside=false;visual?.enter(false);refresh()}else enter()};$('.brand').onclick=e=>{e.preventDefault();go(actor)};$('#settings').onclick=settings;$('#identity').onclick=settings;$('#partner-peek').onclick=()=>go(1-world);$('#zoom-in').onclick=()=>visual?.zoom(.12);$('#zoom-out').onclick=()=>visual?.zoom(-.12);$('#all-memories').onclick=()=>journal();$$('[data-world]').forEach(b=>b.onclick=()=>go(b.dataset.world==='0'?actor:1-actor));$$('[data-action]').forEach(b=>b.onclick=()=>act(b.dataset.action));$$('[data-weather]').forEach(b=>b.onclick=()=>{state.worlds[world].weather=b.dataset.weather;save();refresh()});$$('[data-nav]').forEach(b=>b.onclick=()=>{let a=b.dataset.nav;if(a==='planet'){inside=false;visual?.enter(false);refresh()}else if(a==='home')roomMenu();else act(a)});
try{visual=createScene($('#scene'),act)}catch(e){$('#scene').innerHTML='<div class="error-note">当前设备未能启动 3D 画面。仍可使用右侧和底部按钮体验冰箱、做饭与手账。<br><small>请尝试开启浏览器硬件加速后刷新。</small></div>';console.error('3D unavailable',e)}refresh();
if(document.modelContext?.registerTool){for(const tool of [{name:'read_visible_journal',title:'读取当前角色可见的手账',description:'Read journal records visible to the current demo character.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute(input){if(input&&Object.keys(input).length)throw Error('No arguments accepted');return {actor:names[actor],records:state.events.filter(e=>visible(e)).map(e=>({title:e.title,body:e.body,pending:e.pending}))}}},{name:'navigate_planet',title:'前往自己或对方的星球',description:'Navigate within this local prototype; no journal record is created.',inputSchema:{type:'object',properties:{destination:{type:'string',enum:['own','partner']}},required:['destination'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!['own','partner'].includes(input.destination)||Object.keys(input).some(k=>k!=='destination'))throw Error('Invalid destination');go(input.destination==='own'?actor:1-actor);return {planet:planets[world],owner:names[world]}}}]){try{Promise.resolve(document.modelContext.registerTool(tool)).catch(()=>{})}catch{}}}

